# 기존 BPF 프로그램 (동일)
BPF_PROGRAM = r"""
#include <uapi/linux/ptrace.h>
#include <net/sock.h>
#include <net/inet_sock.h>
#include <linux/tcp.h>
#include <linux/skbuff.h>

struct key_t {
    __u32 saddr;
    __u32 daddr;
    __u16 sport;
    __u16 dport;
};

struct val_t {
    __u64 retrans;     // 누적 재전송
    __u32 srtt_us;     // 최근 RTT(마이크로초, 커널 내부*8에서 보정하여 저장)
    __u32 sndbuf;      // 송신 큐 바이트(sk_wmem_queued)
    __u32 rcvbuf;      // 수신 큐 바이트(sk_rmem_alloc)
};

BPF_HASH(stats, struct key_t, struct val_t, 16384);

static __always_inline int is_mqtt_port(__u16 p_be) {
    __u16 p = bpf_ntohs(p_be);
    return p == 23232; // MQTT
}

static __always_inline int fill_key(struct sock *sk, struct key_t *key) {
    struct inet_sock *inet = (struct inet_sock *)sk;
    if (!inet) return 0;
    // MQTT 소켓만 추적
    if (!(is_mqtt_port(inet->inet_sport) || is_mqtt_port(inet->inet_dport))) return 0;

    key->saddr = inet->inet_saddr;
    key->daddr = inet->inet_daddr;
    key->sport = inet->inet_sport; // big-endian 저장
    key->dport = inet->inet_dport;
    return 1;
}

// ① 재전송 발생 시 누적 카운트 증가
TRACEPOINT_PROBE(tcp, tcp_retransmit_skb) {
    struct sock *sk = (struct sock *)args->skaddr;
    if (!sk) return 0;

    struct key_t k = {};
    if (!fill_key(sk, &k)) return 0;

    struct val_t zero = {};
    struct val_t *v = stats.lookup_or_init(&k, &zero);
    if (v) {
        __sync_fetch_and_add(&v->retrans, 1);
    }
    return 0;
}

// ② 송신 호출 시 sndbuf 샘플링
int kprobe__tcp_sendmsg(struct pt_regs *ctx, struct sock *sk, struct msghdr *msg, size_t size) {
    if (!sk) return 0;
    struct key_t k = {};
    if (!fill_key(sk, &k)) return 0;

    __u32 wmem = 0;
    bpf_probe_read_kernel(&wmem, sizeof(wmem), &sk->sk_wmem_queued);

    struct val_t zero = {};
    struct val_t *v = stats.lookup_or_init(&k, &zero);
    if (v) { v->sndbuf = wmem; }
    return 0;
}

// ③ 수신 경로에서 RTT/rcvbuf 샘플링
int kprobe__tcp_rcv_established(struct pt_regs *ctx, struct sock *sk, struct sk_buff *skb,
                                const struct tcphdr *th, unsigned int len) {
    if (!sk) return 0;
    struct key_t k = {};
    if (!fill_key(sk, &k)) return 0;

    struct tcp_sock *tp = (struct tcp_sock *)sk;
    __u32 srtt = 0;
    bpf_probe_read_kernel(&srtt, sizeof(srtt), &tp->srtt_us);
    if (srtt) srtt >>= 3; // 마이크로초(us)

    __u32 rmem = 0;
    bpf_probe_read_kernel(&rmem, sizeof(rmem), &sk->sk_rmem_alloc);

    struct val_t zero = {};
    struct val_t *v = stats.lookup_or_init(&k, &zero);
    if (v) { v->srtt_us = srtt; v->rcvbuf = rmem; }
    return 0;
}
""";

def ntoa(x):
    try:
        return inet_ntop(AF_INET, struct.pack("!I", x))
    except Exception:
        return inet_ntop(AF_INET, struct.pack("I", x))

def key_to_str(k):
    saddr = ntoa(k[0]); daddr = ntoa(k[1])
    sport = ntohs(k[2]); dport = ntohs(k[3])
    return f"{saddr}:{sport}->{daddr}:{dport}"

class MQTTeBPFEnv(gym.Env):
    """MQTT-eBPF 성능 최적화를 위한 강화학습 환경"""

    def __init__(self):
        super().__init__()

        # 상태 공간: [rtt_norm, retrans_rate, sndbuf_ratio, rcvbuf_ratio, throughput_norm, stability_score]
        self.observation_space = gym.spaces.Box(
            low=0.0, high=1.0, shape=(6,), dtype=np.float32
        )

        # 액션 공간: [throttle_rate, batch_size, qos_level]
        # 연속값으로 정의하고 실제 적용시 이산화
        self.action_space = gym.spaces.Box(
            low=0.0, high=1.0, shape=(3,), dtype=np.float32
        )

        # 메트릭 히스토리
        self.metrics_history = deque(maxlen=50)
        self.reward_history = deque(maxlen=20)

        # 정규화를 위한 기준값들
        self.max_rtt = 150000  # 150ms (us)
        self.max_throughput = 500  # msg/s
        self.max_buffer = 512 * 1024  # 512KB

        # 베이스라인 성능 (기존 결과 기반)
        self.baseline_p99 = 7145.79  # ms
        self.baseline_mean = 5943.44  # ms
        self.baseline_throughput = 264.57  # msg/s

        # 상태 추적
        self.last_action_time = 0
        self.episode_steps = 0
        self.max_episode_steps = 100

    def reset(self):
        """환경 리셋"""
        self.metrics_history.clear()
        self.reward_history.clear()
        self.episode_steps = 0
        self.last_action_time = time.time()
        return self._get_observation()

    def _get_observation(self):
        """현재 상태 관찰"""
        if not self.metrics_history:
            # 초기 중립 상태
            return np.array([0.4, 0.0, 0.3, 0.3, 0.5, 0.5], dtype=np.float32)

        recent = self.metrics_history[-1]

        # RTT 정규화 (0~1)
        rtt_norm = min(recent.get('ewma_rtt_us', 60000) / self.max_rtt, 1.0)

        # 재전송률 (최근 5개 구간의 평균)
        recent_retrans = [m.get('retrans_rate', 0) for m in list(self.metrics_history)[-5:]]
        retrans_rate = min(mean(recent_retrans) if recent_retrans else 0, 1.0)

        # 버퍼 사용률
        sndbuf_ratio = min(recent.get('max_sndbuf', 0) / self.max_buffer, 1.0)
        rcvbuf_ratio = min(recent.get('max_rcvbuf', 0) / self.max_buffer, 1.0)

        # 처리량 정규화
        throughput_norm = min(recent.get('throughput', 250) / self.max_throughput, 1.0)

        # 안정성 점수 (최근 성능의 표준편차 기반)
        recent_rtts = [m.get('avg_rtt_ms', 60) for m in list(self.metrics_history)[-10:]]
        if len(recent_rtts) > 1:
            stability_score = max(0, 1 - (np.std(recent_rtts) / 100))  # 100ms를 기준으로 정규화
        else:
            stability_score = 0.5

        return np.array([rtt_norm, retrans_rate, sndbuf_ratio, rcvbuf_ratio, 
                        throughput_norm, stability_score], dtype=np.float32)

    def step(self, action):
        """액션 실행 및 보상 계산"""
        self.episode_steps += 1

        # 액션을 실제 제어 명령으로 변환
        throttle_rate = max(1, int(action[0] * 20 + 1))  # 1~21 Hz
        batch_size = max(1, int(action[1] * 15 + 1))     # 1~16 배치 크기
        qos_level = int(action[2] * 2)                   # 0, 1, 2 QoS

        # 실제 적용될 제어 명령들
        commands = []

        # 네트워크 상태에 따른 적응적 제어
        current_state = self._get_observation()
        rtt_stress = current_state[0]  # RTT 정규화 값
        buffer_stress = max(current_state[2], current_state[3])  # 최대 버퍼 사용률

        if rtt_stress > 0.8 or buffer_stress > 0.9:  # 심각한 상황
            commands.append({"cmd": "throttle", "rate": max(1, throttle_rate // 2)})
            commands.append({"cmd": "batch", "size": min(batch_size * 2, 20)})
            commands.append({"cmd": "qos", "level": 0})  # 낮은 QoS
        elif rtt_stress > 0.6 or buffer_stress > 0.7:  # 중간 혼잡
            commands.append({"cmd": "throttle", "rate": throttle_rate})
            commands.append({"cmd": "batch", "size": batch_size})
            commands.append({"cmd": "qos", "level": qos_level})
        else:  # 정상 상황
            commands.append({"cmd": "throttle", "rate": min(throttle_rate * 2, 30)})
            commands.append({"cmd": "batch", "size": max(1, batch_size // 2)})
            commands.append({"cmd": "qos", "level": min(qos_level + 1, 2)})

        # 제어 명령 저장 (실제 MQTT 발행은 상위 클래스에서)
        self.last_commands = commands
        self.last_action_time = time.time()

        # 액션 적용 후 짧은 대기 (시스템 반응 시간)
        time.sleep(0.5)

        # 보상 계산
        reward = self._calculate_reward()
        self.reward_history.append(reward)

        # 다음 상태
        next_obs = self._get_observation()

        # 에피소드 종료 조건
        done = self._is_done()

        info = {
            "commands": commands,
            "throttle_rate": throttle_rate,
            "batch_size": batch_size,
            "qos_level": qos_level,
            "reward_components": self._get_reward_components(),
            "episode_steps": self.episode_steps
        }

        return next_obs, reward, done, info

    def _calculate_reward(self):
        """다목적 보상 함수"""
        if len(self.metrics_history) < 2:
            return 0.0

        current = self.metrics_history[-1]
        previous = self.metrics_history[-2]

        # 1. 성능 개선 보상
        rtt_improvement = (previous.get('avg_rtt_ms', 60) - current.get('avg_rtt_ms', 60)) / 10
        throughput_improvement = (current.get('throughput', 250) - previous.get('throughput', 250)) / 10

        # 2. 절대적 성능 보상 (베이스라인 대비)
        current_rtt_ms = current.get('avg_rtt_ms', 60)
        current_throughput = current.get('throughput', 250)

        rtt_absolute = max(0, (self.baseline_mean - current_rtt_ms) / self.baseline_mean)
        throughput_absolute = max(0, (current_throughput - self.baseline_throughput) / self.baseline_throughput)

        # 3. 안정성 보상
        recent_rtts = [m.get('avg_rtt_ms', 60) for m in list(self.metrics_history)[-5:]]
        stability_reward = max(0, 1 - (np.std(recent_rtts) / 50)) if len(recent_rtts) > 1 else 0.5

        # 4. 재전송 페널티
        retrans_penalty = -current.get('retrans_rate', 0) * 5

        # 5. 버퍼 사용률 페널티 (과도한 사용 방지)
        buffer_penalty = -(max(current.get('snd_ratio', 0), current.get('rcv_ratio', 0)) ** 2) * 2

        # 6. 일관성 보상 (최근 보상들의 안정성)
        consistency_reward = 0
        if len(self.reward_history) >= 5:
            recent_rewards = list(self.reward_history)[-5:]
            consistency_reward = max(0, 1 - (np.std(recent_rewards) / 2))

        # 가중 합계
        total_reward = (
            rtt_improvement * 0.25 +        # 즉각적 RTT 개선
            throughput_improvement * 0.20 + # 즉각적 처리량 개선
            rtt_absolute * 0.20 +           # 절대적 RTT 성능
            throughput_absolute * 0.15 +    # 절대적 처리량 성능
            stability_reward * 0.10 +       # 성능 안정성
            retrans_penalty * 0.05 +        # 재전송 페널티
            buffer_penalty * 0.03 +         # 버퍼 사용 페널티
            consistency_reward * 0.02       # 보상 일관성
        )

        return float(total_reward)

    def _get_reward_components(self):
        """보상 구성 요소 분석용"""
        if len(self.metrics_history) < 2:
            return {}

        current = self.metrics_history[-1]
        return {
            "rtt_ms": current.get('avg_rtt_ms', 0),
            "throughput": current.get('throughput', 0),
            "retrans_rate": current.get('retrans_rate', 0),
            "snd_ratio": current.get('snd_ratio', 0),
            "rcv_ratio": current.get('rcv_ratio', 0),
            "episode_steps": self.episode_steps
        }

    def _is_done(self):
        """에피소드 종료 조건"""
        # 최대 스텝 수 도달
        if self.episode_steps >= self.max_episode_steps:
            return True

        # 성능이 너무 나빠진 경우
        if self.metrics_history:
            current = self.metrics_history[-1]
            if current.get('avg_rtt_ms', 60) > 200:  # 200ms 초과
                return True
            if current.get('throughput', 250) < 50:  # 50 msg/s 미만
                return True

        return False

    def update_metrics(self, metrics):
        """외부에서 메트릭 업데이트"""
        self.metrics_history.append(metrics)


class RLEDAAgent:
    """PPO 기반 강화학습 EDA 에이전트"""

    def __init__(self):
        # eBPF 설정
        self.bpf = BPF(text=BPF_PROGRAM)
        print("[OK] eBPF loaded (MQTT:23232; RL-Enhanced)", flush=True)

        # MQTT 클라이언트
        self.mqtt_client = self._setup_mqtt()

        # 강화학습 환경
        self.env = MQTTeBPFEnv()

        # PPO 모델
        self.model = None
        self.is_training = (RL_MODE == "train")

        # 기존 EDA 상태 변수들
        self.prev_totals = {}
        self.last_ctrl_ts = 0.0
        self.ewma_rtt_us = None
        self.rtt_window = deque(maxlen=200)

        # 모델 저장 디렉토리 생성
        os.makedirs(os.path.dirname(MODEL_PATH), exist_ok=True)

    def _setup_mqtt(self):
        """MQTT 클라이언트 설정"""
        client = mqtt.Client(client_id="rl-eda-agent")
        try:
            client.connect(MQTT_HOST, MQTT_PORT, 60)
            client.loop_start()
            print(f"[OK] MQTT connected to {MQTT_HOST}:{MQTT_PORT}", flush=True)
        except Exception as e:
            print(f"[ERROR] MQTT connection failed: {e}", flush=True)
        return client

    def publish_control(self, commands):
        """제어 명령들 발행"""
        try:
            for cmd in commands:
                self.mqtt_client.publish(
                    CONTROL_TOPIC, 
                    payload=json.dumps(cmd), 
                    qos=1
                )
        except Exception as e:
            print(f"[ERROR] MQTT publish failed: {e}", flush=True)

    def train_model(self):
        """PPO 모델 훈련"""
        print(f"[TRAIN] PPO 훈련 시작 (timesteps: {TOTAL_TIMESTEPS})", flush=True)

        # PPO 모델 생성
        self.model = PPO(
            "MlpPolicy",
            self.env,
            verbose=1,
            learning_rate=3e-4,
            n_steps=1024,
            batch_size=64,
            n_epochs=10,
            gamma=0.99,
            gae_lambda=0.95,
            clip_range=0.2,
            ent_coef=0.01,
            vf_coef=0.5,
            max_grad_norm=0.5,
            tensorboard_log=f"{os.path.dirname(MODEL_PATH)}/tensorboard/"
        )

        # 콜백 설정
        callback = TrainingCallback()

        # 훈련 실행
        self.model.learn(
            total_timesteps=TOTAL_TIMESTEPS,
            callback=callback
        )

        # 모델 저장
        self.model.save(MODEL_PATH)
        print(f"[OK] 모델 저장됨: {MODEL_PATH}", flush=True)

    def load_model(self):
        """훈련된 모델 로드"""
        try:
            self.model = PPO.load(MODEL_PATH)
            print(f"[OK] 모델 로드됨: {MODEL_PATH}", flush=True)
            return True
        except Exception as e:
            print(f"[ERROR] 모델 로드 실패: {e}", flush=True)
            return False

    def collect_ebpf_metrics(self):
        """eBPF에서 메트릭 수집 (기존 로직 활용)"""
        now = time.time()
        table = self.bpf.get_table("stats")

        snapshot = {}
        rtt_ms_list = []
        had_retrans = False
        max_sndbuf = 0
        max_rcvbuf = 0
        total_retrans = 0

        for k, v in table.items():
            key = (k.saddr, k.daddr, k.sport, k.dport)
            snapshot[key] = int(v.retrans)

            rtt_ms = float(v.srtt_us) / 1000.0
            sndbuf = int(v.sndbuf)
            rcvbuf = int(v.rcvbuf)
            retrans_total = int(v.retrans)
            retrans_delta = max(0, retrans_total - self.prev_totals.get(key, 0))

            rtt_ms_list.append(rtt_ms)
            if retrans_delta > 0:
                had_retrans = True
                total_retrans += retrans_delta
            if sndbuf > max_sndbuf: max_sndbuf = sndbuf
            if rcvbuf > max_rcvbuf: max_rcvbuf = rcvbuf

        # 평균 RTT 및 EWMA 계산
        avg_rtt_ms = mean(rtt_ms_list) if rtt_ms_list else 60.0
        cur_rtt_us = int(avg_rtt_ms * 1000)

        if self.ewma_rtt_us is None:
            self.ewma_rtt_us = cur_rtt_us
        else:
            self.ewma_rtt_us = int(self.ewma_rtt_us + 0.3 * (cur_rtt_us - self.ewma_rtt_us))

        # 처리량 추정 (간단히 플로우 수 * 평균 RTT 기반)
        num_flows = len(rtt_ms_list)
        estimated_throughput = max(1, num_flows * 50 / max(1, avg_rtt_ms / 50))

        # 버퍼 사용률
        TH_SNDBUF = 256 * 1024
        TH_RCVBUF = 256 * 1024
        snd_ratio = max_sndbuf / max(1, TH_SNDBUF)
        rcv_ratio = max_rcvbuf / max(1, TH_RCVBUF)

        metrics = {
            "timestamp": now,
            "avg_rtt_ms": avg_rtt_ms,
            "ewma_rtt_us": self.ewma_rtt_us,
            "retrans_rate": total_retrans / max(1, len(rtt_ms_list)),
            "max_sndbuf": max_sndbuf,
            "max_rcvbuf": max_rcvbuf,
            "snd_ratio": snd_ratio,
            "rcv_ratio": rcv_ratio,
            "throughput": estimated_throughput,
            "num_flows": num_flows,
            "had_retrans": had_retrans
        }

        self.prev_totals = snapshot
        return metrics

    def run(self):
        """메인 실행 루프"""
        print(f"[START] RL-EDA Agent ({RL_MODE} mode)", flush=True)

        if self.is_training:
            # 훈련 모드
            self.train_model()
            return
        else:
            # 추론 모드
            if not self.load_model():
                print("[ERROR] 모델 로드 실패. 훈련된 모델이 필요합니다.", flush=True)
                return

        # 환경 초기화
        obs = self.env.reset()
        episode_count = 0
        step_count = 0

        print("[START] 추론 모드 실행", flush=True)

        while True:
            try:
                time.sleep(INTERVAL_S)

                # eBPF에서 메트릭 수집
                metrics = self.collect_ebpf_metrics()

                # 환경에 메트릭 업데이트
                self.env.update_metrics(metrics)

                # PPO 모델로 액션 예측
                action, _states = self.model.predict(obs, deterministic=True)

                # 액션 실행
                obs, reward, done, info = self.env.step(action)

                # 제어 명령 발행
                if hasattr(self.env, 'last_commands'):
                    self.publish_control(self.env.last_commands)

                # 로깅
                log_data = {
                    "timestamp": time.time(),
                    "episode": episode_count,
                    "step": step_count,
                    "action": action.tolist(),
                    "reward": float(reward),
                    "metrics": metrics,
                    "control_info": info,
                    "observation": obs.tolist()
                }

                print(json.dumps(log_data), flush=True)

                step_count += 1

                # 에피소드 종료 처리
                if done:
                    print(f"[EPISODE] {episode_count} 종료 (steps: {step_count})", flush=True)
                    obs = self.env.reset()
                    episode_count += 1
                    step_count = 0

            except KeyboardInterrupt:
                print("[STOP] 사용자 종료", flush=True)
                break
            except Exception as e:
                print(f"[ERROR] 실행 중 오류: {e}", flush=True)
                time.sleep(5)  # 오류 후 잠시 대기


class TrainingCallback(BaseCallback):
